const minimumLengthMm = 500;
const maximumLengthMm = 12_000;

const elements = {
  cancelGesture: document.querySelector('#cancel-gesture'),
  cameraStatus: document.querySelector('#camera-status'),
  canvas: document.querySelector('#wall-canvas'),
  dimensionForm: document.querySelector('#dimension-form'),
  error: document.querySelector('#length-error'),
  focusToggle: document.querySelector('#focus-toggle'),
  handleEnd: document.querySelector('#handle-end'),
  input: document.querySelector('#wall-length-input'),
  interaction: document.querySelector('#interaction-message'),
  modeButtons: [...document.querySelectorAll('[data-mode]')],
  numericPanelToggle: document.querySelector('#numeric-panel-toggle'),
  redo: document.querySelector('#redo-button'),
  shell: document.querySelector('.app-shell'),
  status: document.querySelector('#status'),
  undo: document.querySelector('#undo-button'),
  wallLength: document.querySelector('#wall-length'),
  wallPreview: document.querySelector('#wall-preview'),
};

const state = {
  cameraOffset: 0,
  confirmedLengthMm: 2400,
  focusLayout: 'editor',
  gesture: 'idle',
  history: [],
  message: 'Готово к правке стены одним пальцем.',
  mode: 'edit',
  numericPanelOpen: true,
  pointers: new Map(),
  previewLengthMm: null,
  redo: [],
  startLengthMm: 2400,
  startX: 0,
};

const lengthForDisplay = () => state.previewLengthMm ?? state.confirmedLengthMm;

const clampLength = (value) => Math.min(maximumLengthMm, Math.max(minimumLengthMm, value));

const commandLabel = (command) => command?.label || 'перемещение стены';

const setError = (message = '') => {
  elements.error.textContent = message;
  elements.error.hidden = message.length === 0;
};

const announce = (message) => {
  state.message = message;
};

const tryPointerCapture = (method, pointerId) => {
  try {
    elements.canvas[method]?.(pointerId);
  } catch {
    // Synthetic/browser-specific touch dispatch may not create a capturable pointer.
    // The gesture contract remains safe without capture because pointer state is local.
  }
};

const render = () => {
  const isInAppFocus = state.focusLayout === 'in-app';
  const shownLength = lengthForDisplay();
  const wallPercent = 20 + ((shownLength - minimumLengthMm) / (maximumLengthMm - minimumLengthMm)) * 60;
  elements.wallLength.textContent = `Длина стены: ${state.confirmedLengthMm} мм`;
  elements.wallPreview.style.width = state.previewLengthMm === null ? '0%' : `${wallPercent}%`;
  elements.handleEnd.style.left = `calc(${wallPercent}% - 18px)`;
  elements.interaction.textContent = state.previewLengthMm === null
    ? state.message
    : `Предпросмотр: ${state.previewLengthMm} мм. Отпустите палец, чтобы подтвердить.`;
  elements.cameraStatus.textContent = state.cameraOffset === 0
    ? 'Камера: без смещения'
    : `Камера: смещение ${state.cameraOffset} px`;
  elements.cancelGesture.disabled = state.previewLengthMm === null;
  elements.undo.disabled = state.history.length === 0;
  elements.redo.disabled = state.redo.length === 0;
  elements.undo.setAttribute('aria-label', `Отменить: ${commandLabel(state.history.at(-1))}`);
  elements.redo.setAttribute('aria-label', state.redo.length === 0
    ? 'Повторить последнюю команду'
    : `Повторить: ${commandLabel(state.redo.at(-1))}`);
  elements.modeButtons.forEach((button) => {
    button.setAttribute('aria-pressed', String(button.dataset.mode === state.mode));
  });
  elements.shell.dataset.focusLayout = state.focusLayout;
  elements.shell.classList.toggle('is-focus', isInAppFocus);
  elements.focusToggle.textContent = isInAppFocus ? 'Выйти из Фокуса' : 'Войти в Фокус';
  elements.focusToggle.setAttribute('aria-label', isInAppFocus ? 'Выйти из Фокуса' : 'Войти в Фокус');
  elements.focusToggle.setAttribute('aria-pressed', String(isInAppFocus));
  elements.numericPanelToggle.hidden = !isInAppFocus;
  elements.numericPanelToggle.textContent = state.numericPanelOpen ? 'Свернуть точный размер' : 'Открыть точный размер';
  elements.numericPanelToggle.setAttribute('aria-label', state.numericPanelOpen ? 'Свернуть точный размер' : 'Открыть точный размер');
  elements.numericPanelToggle.setAttribute('aria-expanded', String(state.numericPanelOpen));
  elements.dimensionForm.hidden = isInAppFocus && !state.numericPanelOpen;
  const modeText = state.mode === 'edit' ? 'Правка стены' : 'Камера';
  const focusModeText = state.mode === 'edit' ? 'Правка' : 'Камера';
  elements.status.textContent = isInAppFocus
    ? `Фокус · ${focusModeText}`
    : `Режим: ${modeText}${state.message ? ` · ${state.message}` : ''}`;
  elements.input.value = String(state.confirmedLengthMm);
};

const commitLength = (nextLengthMm, label, message) => {
  if (nextLengthMm === state.confirmedLengthMm) {
    announce(`Без изменений: ${nextLengthMm} мм.`);
    render();
    return;
  }

  state.history.push({ from: state.confirmedLengthMm, label, to: nextLengthMm });
  state.redo = [];
  state.confirmedLengthMm = nextLengthMm;
  state.previewLengthMm = null;
  state.gesture = 'idle';
  announce(message);
  render();
};

const resetPreviewForCamera = () => {
  state.previewLengthMm = null;
  state.gesture = 'camera';
  announce('Навигация камеры двумя пальцами — стена не изменяется.');
};

elements.canvas.addEventListener('pointerdown', (event) => {
  if (event.pointerType !== 'touch') return;
  event.preventDefault();
  tryPointerCapture('setPointerCapture', event.pointerId);
  state.pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });

  if (state.pointers.size >= 2) {
    resetPreviewForCamera();
    render();
    return;
  }

  if (state.mode === 'edit') {
    state.gesture = 'edit';
    state.startLengthMm = state.confirmedLengthMm;
    state.startX = event.clientX;
    announce('Потяните одним пальцем для предпросмотра; два пальца — только камера.');
  } else {
    state.gesture = 'camera';
    announce('Навигация камеры одним пальцем. Стена не изменяется.');
  }
  render();
});

elements.canvas.addEventListener('pointermove', (event) => {
  if (!state.pointers.has(event.pointerId)) return;
  event.preventDefault();
  const previous = state.pointers.get(event.pointerId);
  state.pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });

  if (state.pointers.size >= 2) {
    state.cameraOffset += Math.round(event.clientX - previous.x);
    resetPreviewForCamera();
    render();
    return;
  }

  if (state.mode === 'edit' && state.gesture === 'edit') {
    const deltaMm = Math.round((event.clientX - state.startX) * 10);
    state.previewLengthMm = clampLength(state.startLengthMm + deltaMm);
    render();
    return;
  }

  if (state.gesture === 'camera') {
    state.cameraOffset += Math.round(event.clientX - previous.x);
    announce('Навигация камеры. Стена не изменяется.');
    render();
  }
});

elements.canvas.addEventListener('pointerup', (event) => {
  if (!state.pointers.has(event.pointerId)) return;
  event.preventDefault();
  state.pointers.delete(event.pointerId);
  tryPointerCapture('releasePointerCapture', event.pointerId);

  if (state.pointers.size > 0) {
    render();
    return;
  }

  if (state.gesture === 'edit' && state.previewLengthMm !== null) {
    commitLength(state.previewLengthMm, 'перемещение стены', `Подтверждено: ${state.previewLengthMm} мм.`);
    return;
  }

  state.gesture = 'idle';
  announce(state.mode === 'camera' || state.cameraOffset !== 0
    ? 'Навигация завершена. Стена не изменялась.'
    : 'Готово к правке стены одним пальцем.');
  render();
});

elements.canvas.addEventListener('pointercancel', () => {
  state.pointers.clear();
  state.previewLengthMm = null;
  state.gesture = 'idle';
  announce(`Жест прерван. Длина стены: ${state.confirmedLengthMm} мм.`);
  render();
});

elements.cancelGesture.addEventListener('click', () => {
  state.pointers.clear();
  state.previewLengthMm = null;
  state.gesture = 'idle';
  announce(`Изменение отменено. Длина стены: ${state.confirmedLengthMm} мм.`);
  render();
});

elements.modeButtons.forEach((button) => {
  button.addEventListener('click', () => {
    state.mode = button.dataset.mode;
    state.pointers.clear();
    state.previewLengthMm = null;
    state.gesture = 'idle';
    announce(state.mode === 'edit'
      ? 'Готово к правке стены одним пальцем.'
      : 'Камера: навигация без изменения стены.');
    render();
  });
});

elements.focusToggle.addEventListener('click', () => {
  const enteringFocus = state.focusLayout !== 'in-app';
  state.focusLayout = enteringFocus ? 'in-app' : 'editor';
  state.numericPanelOpen = !enteringFocus;
  announce(enteringFocus
    ? 'Фокус включён в приложении. Панели свёрнуты, canvas получает больше места.'
    : 'Обычный editor восстановлен. Значения и история сохранены.');
  render();
});

elements.numericPanelToggle.addEventListener('click', () => {
  state.numericPanelOpen = !state.numericPanelOpen;
  announce(state.numericPanelOpen
    ? 'Точный размер развёрнут в потоке. История остаётся ниже формы.'
    : 'Точный размер свёрнут. Откройте его явной кнопкой при необходимости.');
  render();
});

elements.dimensionForm.addEventListener('submit', (event) => {
  event.preventDefault();
  const rawValue = elements.input.value.trim();
  if (!/^\d+$/.test(rawValue)) {
    setError(`Введите целое значение от ${minimumLengthMm} до ${maximumLengthMm} мм.`);
    render();
    return;
  }

  const parsed = Number.parseInt(rawValue, 10);
  if (parsed < minimumLengthMm || parsed > maximumLengthMm) {
    setError(`Введите целое значение от ${minimumLengthMm} до ${maximumLengthMm} мм.`);
    render();
    return;
  }

  setError();
  commitLength(parsed, 'точный ввод длины стены', `Изменено точно: ${parsed} мм.`);
});

elements.undo.addEventListener('click', () => {
  const command = state.history.pop();
  if (!command) return;
  state.confirmedLengthMm = command.from;
  state.redo.push(command);
  state.previewLengthMm = null;
  state.gesture = 'idle';
  announce(`Отменено: ${command.label}.`);
  render();
});

elements.redo.addEventListener('click', () => {
  const command = state.redo.pop();
  if (!command) return;
  state.confirmedLengthMm = command.to;
  state.history.push(command);
  state.previewLengthMm = null;
  state.gesture = 'idle';
  announce(`Повторено: ${command.label}.`);
  render();
});

render();
